Function leap <- IsLeapYear(year As Integer)
  Define leap As Boolean;
  leap <- (year Mod 4 = 0 And year Mod 100 <> 0) Or year Mod 400 = 0;
EndFunction

Algorithm Main
  Define year As Integer;
  Read year;
  If IsLeapYear(year) Then
    Write "Leap year";
  Else
    Write "Not a leap year";
  EndIf
EndAlgorithm
